CREATE TABLE IF NOT EXISTS song_stats (id TEXT PRIMARY KEY, played INTEGER NOT NULL DEFAULT 0, solved INTEGER NOT NULL DEFAULT 0, s0 INTEGER NOT NULL DEFAULT 0, s1 INTEGER NOT NULL DEFAULT 0, s2 INTEGER NOT NULL DEFAULT 0, s3 INTEGER NOT NULL DEFAULT 0, s4 INTEGER NOT NULL DEFAULT 0, s5 INTEGER NOT NULL DEFAULT 0, s6 INTEGER NOT NULL DEFAULT 0, bad INTEGER NOT NULL DEFAULT 0, x INTEGER NOT NULL DEFAULT 0, total_ms INTEGER NOT NULL DEFAULT 0);

-- upgrade an existing table:
-- ALTER TABLE song_stats ADD COLUMN s5 INTEGER NOT NULL DEFAULT 0;
-- ALTER TABLE song_stats ADD COLUMN s6 INTEGER NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS players (pid TEXT PRIMARY KEY, name TEXT NOT NULL, name_key TEXT NOT NULL UNIQUE, spotify INTEGER NOT NULL DEFAULT 0, points INTEGER NOT NULL DEFAULT 0, solved INTEGER NOT NULL DEFAULT 0, played INTEGER NOT NULL DEFAULT 0, updated INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS scores (pid TEXT NOT NULL, mode TEXT NOT NULL, cur_score INTEGER NOT NULL DEFAULT 0, cur_streak INTEGER NOT NULL DEFAULT 0, cur_solved INTEGER NOT NULL DEFAULT 0, strikes INTEGER NOT NULL DEFAULT 0, best_score INTEGER NOT NULL DEFAULT 0, best_streak INTEGER NOT NULL DEFAULT 0, games INTEGER NOT NULL DEFAULT 0, points INTEGER NOT NULL DEFAULT 0, solved INTEGER NOT NULL DEFAULT 0, played INTEGER NOT NULL DEFAULT 0, updated INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (pid, mode));
CREATE INDEX IF NOT EXISTS scores_by_score ON scores (mode, best_score);
CREATE INDEX IF NOT EXISTS scores_by_streak ON scores (mode, best_streak);
CREATE TABLE IF NOT EXISTS cue_stats (id TEXT NOT NULL, cue INTEGER NOT NULL, played INTEGER NOT NULL DEFAULT 0, fast INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (id, cue));
CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT NOT NULL, t INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS song_stats_played ON song_stats (played);
CREATE INDEX IF NOT EXISTS cue_stats_played ON cue_stats (played);
